   319	    public StatisticsDTO monitoraStatisticheServizio() {
   320	        LocalDate today = LocalDate.now(ZoneId.of("Europe/Rome"));
   321	        List<Reservation> allReservations = reservationRegistry.getAll();
   322	
   323	        int reservationsToday = 0;
   324	        int unconfirmedReservations = 0;
   325	        Set<Long> occupiedSeats = new HashSet<>();
   326	        for (Reservation p : allReservations) {
   327	            if (!today.equals(p.getDate())) {
   328	                continue;
   329	            }
   330	            StatusEnum s = p.getState().getStatusEnum();
   331	            if (s == StatusEnum.ACTIVE || s == StatusEnum.CONFIRMED || s == StatusEnum.COMPLETED) {
   332	                reservationsToday++;
   333	            }
   334	            if (s == StatusEnum.ACTIVE) {
   335	                unconfirmedReservations++;
   336	            }
   337	            if ((s == StatusEnum.ACTIVE || s == StatusEnum.CONFIRMED) && p.getSeat() != null) {
   338	                occupiedSeats.add(p.getSeat().getId());
   339	            }
   340	        }
   341	
   342	        int total = 0;
   343	        for (StudyRoom room : roomRegistry.getAllRooms()) {
   344	            total += room.getTotalSeatCount();
   345	        }
   346	
   347	        StatisticsDTO dto = new StatisticsDTO();
   348	        dto.setReservationsToday(reservationsToday);
   349	        dto.setUnconfirmedReservations(unconfirmedReservations);
   350	        dto.setTotalSeats(total);
   351	        dto.setOccupiedSeatsToday(occupiedSeats.size());
   352	        dto.setOccupancyRate(total > 0 ? (occupiedSeats.size() * 100.0 / total) : 0.0);
   353	        return dto;
   354	    }
