   111	    public void performCheckIn() {
   112	        boolean confirmed = getState().checkIn(this);
   113	        if (!confirmed) {
   114	            throw new IllegalStateException(
   115	                    "Check-in is not permitted in the current status: " + getState().getStatusEnum());
   116	        }
