   140	    public void validateActiveReservationForCurrentDate() {
   141	        if (getState() == null || getState().getStatusEnum() != StatusEnum.ACTIVE) {
   142	            throw new IllegalStateException("The reservation is not in ACTIVE status");
   143	        }
   144	        if (!LocalDate.now(ZoneId.of("Europe/Rome")).equals(date)) {
   145	            throw new IllegalStateException("Check-in is only permitted on the reservation date");
   146	        }
   147	        LocalDateTime deadline = LocalDateTime.of(date, timeSlot.getStartTime())
   148	                .plusMinutes(CHECK_IN_TOLERANCE_MINUTES);
   149	        if (LocalDateTime.now(ZoneId.of("Europe/Rome")).isAfter(deadline)) {
   150	            throw new IllegalStateException("check-in tolerance of " + CHECK_IN_TOLERANCE_MINUTES
   151	                    + " minutes after the time slot began has been exceeded");
   152	        }
   153	    }
   156	    private void validateCancellationWindow() {
   157	        if (date == null || timeSlot == null) {
   158	            throw new IllegalStateException("Reservation has no date or time slot");
   159	        }
   160	        LocalDateTime start = LocalDateTime.of(date, timeSlot.getStartTime());
   161	        if (LocalDateTime.now(ZoneId.of("Europe/Rome")).isAfter(start.minusHours(6))) {
   162	            throw new IllegalStateException(
   163	                    "Cancellation is not permitted less than 6 hours before the time slot starts");
   164	        }
   165	    }
