        if(date == null){
            throw new IllegalArgumentException("A date is required");
        }
        DayOfWeek day = date.getDayOfWeek();
        return !day.equals(DayOfWeek.SATURDAY) && !day.equals(DayOfWeek.SUNDAY);
    }

