    private TimeSlot getWorkingHoursForDate(LocalDate date) {
        if (!isOpenOnDate(date)) {
            return null; // English implementation note.
        }

        int dayIndex = date.getDayOfWeek().getValue() - 1;

        if (timeLavorativo != null && dayIndex < timeLavorativo.size()) {
            return timeLavorativo.get(dayIndex);
        }
        return null;
    }

