    public List<TimeSlot> getScheduledTimeSlots(LocalDate date) {
        TimeSlot dayWorkingHours = getWorkingHoursForDate(date);

        if (dayWorkingHours == null) {
            return new ArrayList<>();
        }

        List<TimeSlot> availableSlotsToday = new ArrayList<>();

        for (TimeSlot slot : timeSlots) {
            boolean startsAfterOpening = !slot.getStartTime().isBefore(dayWorkingHours.getStartTime());
            boolean endsBeforeClosing = !slot.getEndTime().isAfter(dayWorkingHours.getEndTime());

            if (startsAfterOpening && endsBeforeClosing) {
                availableSlotsToday.add(slot);
            }
        }

        return availableSlotsToday;
    }

